package com.oms.supplychain.service.wms;
import com.oms.supplychain.service.warehouse.PurchaseGoodsClient;
import com.ruoyi.common.core.domain.R;
import org.springframework.stereotype.Component;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;
@Component public class WarehouseControlScope {
 @Resource WmsStore db; @Resource WmsConnections connections; @Resource StockMovementClient stock; @Resource PurchaseGoodsClient goods;
 public long n(Map<String,Object>d,String k){return d.get(k)==null?0:id(d.get(k));}
 @SuppressWarnings("unchecked") public Map<String,Object> obj(Object v){try{return v instanceof Map?(Map<String,Object>)v:db.json.readValue(text(v),Map.class);}catch(Exception e){throw new IllegalArgumentException("仓库业务快照损坏");}}
 @SuppressWarnings("unchecked") public List<Map<String,Object>> rows(Object v){require(v instanceof List,"明细缺失");return (List<Map<String,Object>>)v;}
 @SuppressWarnings("unchecked") public List<String> skus(Object v){require(v instanceof List&&!((List<?>)v).isEmpty()&&((List<?>)v).size()<=100,"每次请选择1至100个SKU");TreeSet<String>r=new TreeSet<>();for(Object a:(List<?>)v){String s=text(a);require(!s.isEmpty()&&s.length()<=128&&r.add(s),"SKU重复或过长");}return new ArrayList<>(r);}
 public String hash(Object v){return QimenProtocol.hash("SHA-256",db.encode(v));}
 public String safe(Exception e){String s=e instanceof IllegalArgumentException?text(e.getMessage()):"执行结果未确认，请刷新后沿用原单重试";return s.substring(0,Math.min(950,s.length()));}
 public Map<String,Object> reply(R<Map<String,Object>> r){require(r!=null&&R.isSuccess(r)&&r.getData()!=null,r==null?"库存服务结果未确认":text(r.getMsg()));return r.getData();}
 public Map<String,Object> warehouse(String c,String store){Map<String,Object>w=db.one("SELECT v.*,r.owner_id,r.real_store_id,r.status relation_status,o.owner_code actual_owner,o.is_enable owner_status,w.real_store_code,w.wms_name,w.status real_status,w.director,w.mobile_phone,w.province,w.city,w.district,w.address FROM wms_simulation_store_info v JOIN owner_warehouse r ON r.company_key=v.company_key AND r.id=v.owner_warehouse_id JOIN owner_info o ON o.company_key=r.company_key AND o.id=r.owner_id JOIN wms_real_store_info w ON w.company_key=r.company_key AND w.id=r.real_store_id WHERE v.company_key=? AND v.wms_simulation_code=?",c,store);for(String k:Arrays.asList("status","relation_status","owner_status","real_status"))require(n(w,k)==2,"仓库、货主或关系未启用");return w;}
 public Map<String,Object> route(String c,Map<String,Object>w){Map<String,Object>connection=connections.usable(c,n(w,"connection_id"));require("QIMEN".equals(connection.get("provider"))&&"2.0".equals(text(connection.get("api_version"))),"库存对账及调拨需要奇门2.0连接");require(!text(w.get("external_owner")).isEmpty()&&!text(w.get("external_warehouse")).isEmpty(),"请维护仓库货主外部映射");return map("connection_id",connection.get("id"),"external_owner",w.get("external_owner"),"external_warehouse",w.get("external_warehouse"));}
 public Map<String,Object> receiver(Map<String,Object>w){for(String k:Arrays.asList("director","mobile_phone","province","city","address"))require(!text(w.get(k)).isEmpty(),"目的实仓收件资料不完整，请维护联系人、电话、省市区及地址");return map("name",w.get("director"),"mobile",w.get("mobile_phone"),"province",w.get("province"),"city",w.get("city"),"area",w.get("district"),"detailAddress",w.get("address"));}
 public List<String> stores(String c,Map<String,Object>w){List<Map<String,Object>>r=db.jdbc.queryForList("SELECT v.wms_simulation_code,v.connection_id,v.external_owner,v.external_warehouse FROM wms_simulation_store_info v JOIN owner_warehouse ow ON ow.company_key=v.company_key AND ow.id=v.owner_warehouse_id WHERE v.company_key=? AND ow.owner_id=? AND ow.real_store_id=? ORDER BY v.id LIMIT 51",c,w.get("owner_id"),w.get("real_store_id"));require(r.size()<=50,"该货主实仓下虚仓超过50个，请先拆分仓库组织");List<String>s=new ArrayList<>();for(Map<String,Object>a:r){if(a.get("connection_id")!=null)for(String k:Arrays.asList("connection_id","external_owner","external_warehouse"))require(text(a.get(k)).equals(text(w.get(k))),"同货主同实仓的虚仓外部映射不一致，不能重复或混合对账");s.add(text(a.get("wms_simulation_code")));}Collections.sort(s);return s;}
 public Map<String,Object> snapshot(String c,List<String>stores,List<String>skus){return reply(stock.execute(c,"snapshot",map("stores",stores,"skus",skus)));}
 public List<Map<String,Object>> options(String c){return db.jdbc.queryForList("SELECT v.wms_simulation_code store_code,v.wms_simulation_name store_name,o.owner_code,o.owner_name,w.real_store_code,w.wms_name real_name,v.inbound_mode,v.outbound_mode FROM wms_simulation_store_info v JOIN owner_warehouse r ON r.company_key=v.company_key AND r.id=v.owner_warehouse_id JOIN owner_info o ON o.company_key=r.company_key AND o.id=r.owner_id JOIN wms_real_store_info w ON w.company_key=r.company_key AND w.id=r.real_store_id WHERE v.company_key=? AND v.status=2 AND r.status=2 AND o.is_enable=2 AND w.status=2 ORDER BY v.id DESC LIMIT 200",c);}
 public Map<String,Map<String,Object>> goods(String c,List<String>skus){R<List<Map<String,Object>>>r=goods.lookupBatch(skus,c,"inner");require(r!=null&&R.isSuccess(r)&&r.getData()!=null,"商品资料批量核对失败");Map<String,Map<String,Object>>m=new HashMap<>();for(Map<String,Object>g:r.getData()){require(Boolean.TRUE.equals(g.get("purchase_valid")),"请选择具有实际仓库库存的组件或实物套装");m.put(text(g.get("sku_sn")),g);}require(m.size()==skus.size(),"部分SKU资料不存在");return m;}
 public Map<String,Map<String,Object>> checkGoods(String c,List<String>skus){Map<String,Map<String,Object>>m=new HashMap<>();try{R<List<Map<String,Object>>>r=goods.lookupBatch(skus,c,"inner");if(r!=null&&R.isSuccess(r)&&r.getData()!=null)for(Map<String,Object>g:r.getData())m.put(text(g.get("sku_sn")),g);}catch(Exception e){/* Inventory evidence remains useful even when catalog metadata is unavailable. */}return m;}
 public void audit(String c,String kind,long id,String action,String actor,String reason){db.insert("warehouse_control_audit",map("company_code",c,"kind",kind,"document_id",id,"action",action,"actor",actor,"reason",reason.substring(0,Math.min(1500,reason.length()))));}
 public List<Map<String,Object>> audit(String c,String kind,long id){List<Map<String,Object>>r=db.jdbc.queryForList("SELECT action,actor,reason,create_time FROM warehouse_control_audit WHERE company_code=? AND kind=? AND document_id=? ORDER BY id DESC LIMIT 100",c,kind,id);for(Map<String,Object>d:r)ReturnQueryWarehouse.formatTimes(d);return r;}
 public void version(Map<String,Object>d,Map<String,Object>cmd){require(n(d,"control_version")==id(cmd.get("control_version")),"单据已变化，请刷新核对");}
 public Map<String,Object> page(String c,String table,Map<String,String>q,String extra){String sn=text(q.get("document_sn")),state=text(q.get("state")),from=text(q.get("from")),to=text(q.get("to"));require(sn.length()<=64&&state.matches("[A-Z_]{0,24}"),"筛选无效");int page=q.containsKey("pageNum")?Math.toIntExact(id(q.get("pageNum"))):1,size=q.containsKey("pageSize")?Math.toIntExact(id(q.get("pageSize"))):20;require(page>0&&page<=10000&&size>0&&size<=50,"每页最多50条");String where=" WHERE company_code=?"+(table.equals("warehouse_reconciliation")?" AND parent_id=0":"");List<Object>a=new ArrayList<>(Collections.singletonList(c));if(!sn.isEmpty()){where+=" AND document_sn=?";a.add(sn);}if(!state.isEmpty()){where+=" AND state=?";a.add(state);}if(from.isEmpty()&&to.isEmpty()&&sn.isEmpty()){from=java.time.LocalDate.now().minusDays(90).toString();to=java.time.LocalDate.now().toString();}if(!from.isEmpty()||!to.isEmpty()){try{java.time.LocalDate b=java.time.LocalDate.parse(from),e=java.time.LocalDate.parse(to);require(!e.isBefore(b)&&!e.isAfter(b.plusDays(93)),"日期范围最多93天");where+=" AND create_time>=? AND create_time<?";a.add(b.toString());a.add(e.plusDays(1).toString());}catch(java.time.format.DateTimeParseException e){throw new IllegalArgumentException("请完整选择有效日期");}}long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM "+table+where,Long.class,a.toArray());a.add(size);a.add((page-1)*size);List<Map<String,Object>>r=db.jdbc.queryForList("SELECT id,document_sn,state,create_time,"+extra+" FROM "+table+where+" ORDER BY id DESC LIMIT ? OFFSET ?",a.toArray());for(Map<String,Object>d:r)ReturnQueryWarehouse.formatTimes(d);return map("rows",r,"total",total);}
}
